// Concatenate the PageLoad.scripts (classic, order-dependent) into ONE file so
// boot costs one round trip instead of ~80. The list is extracted from
// js/main.js — the single source of truth — so adding a script there is enough.
// Modules (:MODULE) and anything unreadable are SKIPPED here and left to the
// runtime per-file path, which stays as the fallback.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const main = readFileSync('js/main.js', 'utf8');
const m = main.match(/static scripts = \[([\s\S]*?)\];/);
if (!m) { console.error('boot-bundle: scripts list not found'); process.exit(1); }
const list = [...m[1].matchAll(/'([^']+)'/g)].map(x => x[1]);
let out = '// generated by scripts/make-boot-bundle.mjs — do not edit\n';
let bundled = 0, skipped = [];
for (const src of list) {
  if (src.endsWith(':MODULE')) { skipped.push(src); continue; }
  try {
    out += '\n;/* ==== ' + src + ' ==== */\n' + readFileSync(src, 'utf8') + '\n//# sourceURL=' + src + '\n';
    bundled++;
  } catch (e) { skipped.push(src); }
}
mkdirSync('dist/js', { recursive: true });
writeFileSync('dist/js/boot-bundle.js', out);
writeFileSync('dist/js/boot-bundle.json', JSON.stringify({ bundled, skipped }));
console.log('boot-bundle:', bundled, 'bundled,', skipped.length, 'left to runtime', skipped);
